/* Authored Java core. The 40-lesson chapter target is NOT yet fully authored.
 * Examples are didactic fragments in modern Java unless their surrounding class/method context is included.
 */
(function () {
  'use strict';
  let serial = 0;
  const q = (prompt, correct, wrong, explanation, code) => {
    const options = [correct, ...wrong]; const answer = serial++ % options.length;
    for (let i = 0; i < answer; i++) options.unshift(options.pop());
    return {type:'choice',prompt,options,answer,explanation,...(code?{code}:{})};
  };
  const t = (prompt, accepted, explanation, code) => ({type:'text',prompt,accepted:Array.isArray(accepted)?accepted:[accepted],explanation,...(code?{code}:{})});
  const g = (prompt, accepted, explanation, code) => ({...t(prompt,accepted,explanation,code),type:'gap'});
  const o = (prompt, steps, explanation) => { const order=steps.map((_,i)=>i).reverse(); return {type:'order',prompt,options:order.map(i=>steps[i]),answer:steps.map((_,i)=>order.indexOf(i)),explanation}; };
  const p = (prompt,pairs,explanation) => ({type:'pairs',prompt,pairs,explanation});
  const chapters=[];
  function chapter(title, unitNames, lessonTitle, theory, activities) {
    const n=chapters.length+1, prefix=`java-c${String(n).padStart(2,'0')}`;
    chapters.push({id:prefix,title,description:theory.split('. ')[0]+'.',targetLessonCount:40,authoringStatus:'partial',reviewStatus:'technical-review-pending',
      units:unitNames.map((name,i)=>({id:`${prefix}-u${i+1}`,title:name,objective:`Aplicar ${name.toLowerCase()} em Java e explicar o resultado.`,targetLessonCount:5,authoringStatus:i===0?'partial':'planned',lessons:i===0?[{id:`${prefix}-u1-l1`,title:lessonTitle,theory,activities:activities.map((a,j)=>({...a,id:`${prefix}-u1-l1-a${j+1}`}))}]:[]}))});
  }

  chapter('Introdução, JDK, JVM e primeiro programa',
    ['JDK e JVM','Instalação','Classe inicial','Método main','Compilação','Execução','Entrada e saída','Diagnóstico de erros'],
    'Painel de boas-vindas no terminal',
    'Java separa o kit de desenvolvimento da máquina virtual que executa o programa. O JDK reúne ferramentas como o compilador javac, capaz de transformar um arquivo .java em bytecode armazenado em um arquivo .class. Em seguida, o comando java aciona a JVM para carregar a classe inicial e executar seu método main. Quando o nome da classe pública não coincide com o nome do arquivo, a compilação falha antes mesmo de produzir qualquer saída no terminal.',[
      q('Para compilar código-fonte Java em uma máquina nova, qual pacote precisa estar instalado?','O JDK (Java Development Kit)',['Apenas um leitor de arquivos PDF','Somente um arquivo .class isolado'],'O JDK inclui o compilador javac e demais utilitários de desenvolvimento, além do ambiente de execução.'),
      t('Qual texto exato aparece no console ao executar a instrução de saída abaixo, sem aspas?','Painel ativo','System.out.println escreve o conteúdo textual da string e encerra a linha.','System.out.println("Painel ativo");'),
      g('Complete o nome do método ponto de entrada reconhecido pela JVM ao iniciar a classe Painel.','main','A JVM procura a assinatura public static void main(String[] args) para iniciar a execução padrão.','public class Painel {\n    public static void ____(String[] args) {\n        System.out.println("Pronto");\n    }\n}'),
      p('Relacione cada item do ecossistema Java à sua responsabilidade.',[['javac','Compilar código-fonte .java em bytecode .class'],['JVM','Carregar e executar o bytecode compilado'],['Painel.java','Arquivo de texto com o código-fonte'],['Painel.class','Arquivo gerado com o bytecode da classe']],'Código-fonte, compilador, bytecode e máquina virtual cumprem etapas distintas.'),
      o('Ordene os passos no terminal para compilar e rodar a classe pública Painel.',['Salvar o código-fonte no arquivo Painel.java','Executar javac Painel.java para gerar o bytecode','Verificar que o arquivo Painel.class foi produzido','Executar java Painel para iniciar o programa na JVM'],'Primeiro salvamos e compilamos o arquivo .java; depois iniciamos a classe compilada com o comando java.'),
      q('O arquivo Painel.java declara public class Aviso. O que ocorre ao rodar javac Painel.java?','O compilador relata erro porque a classe pública deve ter o mesmo nome do arquivo',['O arquivo é renomeado sozinho pelo terminal','A JVM ignora o erro e imprime Aviso automaticamente'],'Em Java, toda classe declarada como public precisa estar em um arquivo .java de mesmo nome exato.'),
      t('Qual extensão identifica o arquivo de bytecode gerado após compilar Painel.java com javac?',['.class','class'],'O compilador javac traduz cada classe do código-fonte para um arquivo .class.'),
      q('Ao iniciar a aplicação compilada com o comando tradicional java Painel, por que não passamos Painel.class?','Porque o comando java recebe o nome da classe a carregar, e não o nome do arquivo .class',['Porque a JVM apaga o arquivo .class antes de ler','Porque classes Java não possuem nome próprio após compilar'],'Na invocação clássica de classes compiladas, informamos o nome qualificado da classe, sem a extensão .class.')
    ]);

  chapter('Lógica, algoritmos e fluxogramas',
    ['Problemas e algoritmos','Entradas e saídas','Símbolos','Montagem de fluxos','Condições','Repetições','Rastreamento','Validação'],
    'Tarifa de estacionamento por tempo',
    'Resolver um problema com clareza exige definir entradas, regras de decisão e saída antes de digitar código Java. Em um estacionamento, estadias de até 60 minutos custam 8 reais; acima de 60 minutos, acrescenta-se uma taxa fixa de 5 reais ao valor base. No fluxograma, o losango avalia a condição sobre os minutos e conduz o fluxo pelo ramo verdadeiro ou falso até a etapa final de exibição. Testar valores na fronteira exata de 60 minutos confirma que a regra não cobra acréscimo indevido.',[
      q('Qual dado constitui a entrada necessária para calcular a tarifa desse estacionamento?','A quantidade de minutos de permanência do veículo',['O valor final da tarifa já somado','A cor da cancela desenhada na tela'],'O algoritmo recebe o tempo em minutos para decidir se aplica apenas a base ou também o acréscimo.'),
      t('Segundo a regra descrita (base 8 e acréscimo 5 acima de 60 minutos), qual tarifa inteira é cobrada para 75 minutos?','13','Como 75 é maior que 60, somamos o valor base 8 ao acréscimo 5: 8 + 5 = 13.'),
      q('Para uma estadia de exatamente 60 minutos, qual é o resultado da condição minutos > 60?','Falso, mantendo a tarifa em 8 reais',['Verdadeiro, somando 5 reais à tarifa','Erro lógico, pois números iguais não podem ser comparados'],'O operador > exige valor estritamente maior; em 60 minutos a condição é falsa e não há acréscimo.'),
      p('Associe cada forma do fluxograma de estacionamento à etapa que ela representa.',[['Oval','Início ou encerramento do cálculo da tarifa'],['Paralelogramo','Leitura dos minutos ou exibição do valor a pagar'],['Losango','Pergunta minutos > 60?'],['Retângulo','Cálculo tarifa = 8 + 5']],'Símbolos padronizados separam terminais, entrada/saída, decisão e processamento.'),
      o('Monte a sequência do algoritmo para um veículo que permaneceu 90 minutos.',['Ler o tempo de permanência de 90 minutos','Definir a tarifa base inicial como 8','Constatar que 90 > 60 é verdadeiro','Somar 5 à tarifa para obter 13','Exibir a tarifa final calculada'],'Lemos a entrada, partimos da base, avaliamos a condição e atualizamos o valor antes de exibir.'),
      g('Complete o operador relacional para cobrar o acréscimo somente acima de 60 minutos.','>','A regra especifica acima de 60 minutos; logo, 60 permanece sem taxa extra.','int tarifa = 8;\nif (minutos ____ 60) {\n    tarifa += 5;\n}'),
      q('Qual trio de entradas valida melhor a fronteira da regra minutos > 60?','59, 60 e 61 minutos',['120, 180 e 240 minutos','Apenas 10 minutos repetido três vezes'],'Testar imediatamente abaixo, exatamente no limite e logo acima revela erros entre > e >=.'),
      t('Acompanhe o rastreamento e informe o valor final de tarifa para minutos = 45.','8','Para 45 minutos, 45 > 60 é falso; o bloco if não executa e tarifa permanece 8.','int minutos = 45;\nint tarifa = 8;\nif (minutos > 60) {\n    tarifa = tarifa + 5;\n}')
    ]);

  chapter('Variáveis, tipos e operadores',
    ['Tipos primitivos','Declarações','Strings','Conversões','Aritmética','Comparações','Booleanos','Precisão numérica'],
    'Conversão de medidas e lotes na fábrica',
    'Em Java, tipos primitivos como int, long, double e boolean guardam valores diretamente e definem quais operações são válidas. Dividir dois valores int descarta a parte fracionária, o que é útil para contar caixas completas, mas exige conversão explícita para double quando queremos a razão exata. Já o operador % calcula o resto da divisão inteira. Para valores monetários que exigem precisão decimal exata, usa-se BigDecimal a partir de String em vez de ponto flutuante binário.',[
      t('Qual número inteiro é impresso pelo cálculo de caixas completas abaixo?','4','Na divisão inteira 23 / 5, cabem 4 grupos de 5 e a fração é descartada.','int pecas = 23;\nint caixas = pecas / 5;\nSystem.out.println(caixas);'),
      g('Complete o operador que obtém quantas peças sobram fora das caixas de 5 unidades.','%','O operador módulo (%) devolve o resto da divisão inteira: 23 % 5 resulta em 3.','int sobra = 23 ____ 5;'),
      q('Qual expressão em Java calcula a média com casas decimais a partir de int soma = 7 e int qtd = 2?','(double) soma / qtd',['(double) (soma / qtd)','soma / qtd'],'Converter soma antes da divisão promove a operação para double (3.5); converter depois apenas transforma 3 em 3.0.'),
      p('Relacione cada declaração Java ao tipo de dado representado.',[['int lote = 120;','Inteiro primitivo de 32 bits'],['long serie = 9_000_000_000L;','Inteiro primitivo de 64 bits com sufixo L'],['boolean aprovado = true;','Valor lógico verdadeiro ou falso'],['BigDecimal preco = new BigDecimal("19.90");','Decimal exato adequado para valores monetários']],'Cada tipo atende a uma faixa e necessidade de precisão diferente em Java.'),
      t('Respeitando a precedência de operadores em Java, qual é o valor final armazenado em resultado?','19','A multiplicação 3 * 5 ocorre primeiro (15) e depois soma-se 4, totalizando 19.','int resultado = 4 + 3 * 5;'),
      q('Duas variáveis String distintas contêm o texto "LOTE-9". Qual forma compara o conteúdo textual com segurança?','codigoA.equals(codigoB)',['codigoA == codigoB','codigoA = codigoB'],'Em objetos como String, == compara referências na memória, enquanto equals compara a sequência de caracteres.'),
      o('Ordene as etapas para converter o texto "48" em inteiro e calcular o dobro de unidades.',['Receber a String texto com o valor "48"','Converter texto para int usando Integer.parseInt(texto)','Multiplicar o inteiro obtido por 2','Exibir o resultado numérico 96'],'A conversão textual com Integer.parseInt deve ocorrer antes da multiplicação aritmética.'),
      q('Por que new BigDecimal("0.1") é preferível a new BigDecimal(0.1) em cálculos financeiros?','Porque o literal double 0.1 já carrega imprecisão binária antes de chegar ao BigDecimal',['Porque BigDecimal não aceita números positivos sem sinal','Porque Strings são somadas automaticamente sem métodos'],'Construir BigDecimal a partir de String ou BigDecimal.valueOf preserva a representação decimal exata.')
    ]);

  chapter('Condições, laços e rastreamento',
    ['If e else','Switch','For','While','Do while','Break e continue','Acumuladores','Depuração de laços'],
    'Triagem de sensores em uma estufa',
    'Estruturas de controle coordenam decisões e varreduras repetidas sobre leituras de um sistema. Expressões switch modernas com setas (->) selecionam um valor diretamente sem queda acidental entre casos (fall-through). Em um laço for ou while, um acumulador soma leituras válidas, continue ignora medições descartadas e break interrompe a varredura diante de um alerta crítico. Rastrear passo a passo cada variável impede erros de limite por uma unidade.',[
      t('Qual texto sem aspas é atribuído a faixa pela expressão switch abaixo quando nivel vale 2?','Alerta','O ramo case 2 -> devolve diretamente a String "Alerta", sem executar os demais casos.','int nivel = 2;\nString faixa = switch (nivel) {\n    case 1 -> "Normal";\n    case 2 -> "Alerta";\n    default -> "Crítico";\n};'),
      t('Rastreie o laço de números pares abaixo e informe o valor final de soma.','12','O laço percorre i = 2, 4 e 6: soma acumula 0 + 2 + 4 + 6 = 12 (para quando i chega a 8).','int soma = 0;\nfor (int i = 2; i <= 6; i += 2) {\n    soma += i;\n}'),
      g('Complete a instrução que pula leituras negativas e segue para a próxima iteração do laço.','continue','continue ignora o restante da iteração atual e avança para o próximo passo do for.','for (int leitura : leituras) {\n    if (leitura < 0) ____;\n    total += leitura;\n}'),
      q('Ao detectar temperatura acima de 50 graus, o sistema deve encerrar imediatamente o laço de leitura. Qual palavra-chave usar?','break',['continue','default'],'break interrompe o laço mais interno imediatamente, transferindo o fluxo para após o bloco de repetição.'),
      p('Associe cada estrutura de controle Java ao cenário em que ela se encaixa melhor.',[['switch com ->','Mapear um código discreto diretamente para uma resposta sem fall-through'],['for clássico','Repetir com contador inicializado, condição e passo visíveis no cabeçalho'],['while','Repetir enquanto uma condição for verdadeira, podendo executar zero vezes'],['do-while','Executar o bloco ao menos uma vez antes de testar a condição de saída']],'Conhecer a garantia de execução mínima e o propósito de cada construção torna o código mais legível.'),
      o('Ordene o rastreamento de um laço while que conta leituras positivas antes do sentinela 0 na fila [18, 21, 0, 19].',['Inicializar o contador validas com 0','Ler 18, ver que é diferente de 0 e incrementar validas para 1','Ler 21, ver que é diferente de 0 e incrementar validas para 2','Ler o sentinela 0 e encerrar a condição do while','Concluir o trecho com validas igual a 2'],'O sentinela 0 encerra a repetição antes que o valor 19 posterior seja processado.'),
      q('Qual condição booleana expressa que a umidade u está dentro da faixa segura de 40 até 70, inclusive?','u >= 40 && u <= 70',['u >= 40 || u <= 70','40 <= u <= 70'],'Java não aceita comparações encadeadas como 40 <= u <= 70, e || seria verdadeiro para qualquer número.'),
      q('Em um laço for (int i = 0; i <= 3; i++), quantas iterações acontecem no total?','4 iterações (para i igual a 0, 1, 2 e 3)',['3 iterações (para i igual a 0, 1 e 2)','Infinitas iterações, pois i começa em zero'],'Usar <= inclui o limite superior 3; começando em 0, os valores visitados são 0, 1, 2 e 3.')
    ]);

  chapter('Métodos, escopo e recursão',
    ['Assinaturas','Parâmetros','Retornos','Escopo','Sobrecarga','Passagem por valor','Caso-base','Recursão'],
    'Cálculo de frete e decomposição de pacotes',
    'Métodos organizam regras em unidades nomeadas com assinatura composta pelo nome e pelos tipos dos parâmetros. Java permite sobrecarga (overloading) quando métodos de mesmo nome diferem na lista de parâmetros, e passa argumentos sempre por valor: alterar um parâmetro primitivo dentro do método não muda a variável original de quem chamou. Em métodos recursivos, um caso-base obrigatório interrompe as chamadas enquanto o passo recursivo reduz a entrada rumo a essa parada.',[
      t('Qual valor numérico é exibido na saída após chamar zerarCopia(peso)?','15','Java passa tipos primitivos por cópia do valor; atribuir 0 ao parâmetro x não altera a variável peso no chamador.','static void zerarCopia(int x) {\n    x = 0;\n}\n// No método main:\nint peso = 15;\nzerarCopia(peso);\nSystem.out.println(peso);'),
      q('Uma classe já possui static int frete(int pesoKg). Qual assinatura abaixo configura uma sobrecarga válida?','static int frete(int pesoKg, boolean expresso)',['static double frete(int quilos)','static int frete(int volume)'],'Em Java, a sobrecarga exige lista de tipos de parâmetros diferente; mudar apenas o retorno ou o nome do parâmetro não basta.'),
      g('Complete a comparação do caso-base para que somaAte(0) encerre a recursão devolvendo 0.',['==','<='],'Quando n chega a 0, o método retorna imediatamente sem fazer nova chamada recursiva.','static int somaAte(int n) {\n    if (n ____ 0) return 0;\n    return n + somaAte(n - 1);\n}'),
      t('Usando o método recursivo somaAte(int n) abaixo, qual valor somaAte(4) devolve?','10','somaAte(4) calcula 4 + 3 + 2 + 1 + 0, resultando em 10.','static int somaAte(int n) {\n    if (n == 0) return 0;\n    return n + somaAte(n - 1);\n}'),
      p('Relacione cada conceito de métodos em Java à sua definição precisa.',[['Assinatura do método','Nome do método combinado à ordem e aos tipos dos parâmetros'],['Escopo local','Região do bloco onde uma variável declarada pode ser lida'],['Sobrecarga','Métodos de mesmo nome na classe com listas de parâmetros distintas'],['Caso-base','Condição que devolve resposta direta e encerra a recursão']],'Dominar assinatura, escopo, sobrecarga e parada recursiva evita erros de compilação e estouro de pilha.'),
      o('Ordene o ciclo de chamadas e retornos ao avaliar potenciaDois(2), onde potenciaDois(0) retorna 1 e potenciaDois(n) retorna 2 * potenciaDois(n - 1).',['Chamar potenciaDois(2), que aguarda potenciaDois(1)','Chamar potenciaDois(1), que aguarda potenciaDois(0)','Atingir o caso-base potenciaDois(0) e retornar 1','Calcular 2 * 1 em potenciaDois(1) e retornar 2','Calcular 2 * 2 em potenciaDois(2) e retornar 4'],'A pilha empilha chamadas até o caso-base e depois desempilha multiplicando cada retorno.'),
      q('O que acontece em tempo de execução se um método recursivo em Java nunca alcançar seu caso-base?','A JVM lança StackOverflowError ao esgotar a pilha de chamadas',['O compilador converte o método automaticamente em um comentário','O método retorna zero silenciosamente na décima chamada'],'Cada chamada pendente ocupa um quadro na pilha da thread até provocar StackOverflowError.'),
      q('Uma variável taxa é declarada dentro de um bloco if em calcularFrete(). Onde taxa existe?','Somente dentro daquele bloco if até sua chave de fechamento',['Em todos os métodos de todas as classes do pacote','Apenas depois que o método calcularFrete() termina'],'Variáveis locais em Java têm escopo limitado ao bloco de chaves onde foram declaradas.')
    ]);

  chapter('Arrays, strings e manipulação de dados',
    ['Arrays','Percursos','Matrizes','Strings imutáveis','StringBuilder','Busca','Ordenação','Transformação'],
    'Normalização de códigos de embarque',
    'Arrays em Java possuem tamanho fixo definido na criação e expõem essa dimensão no atributo length. Objetos String são imutáveis: métodos como trim, toUpperCase e replace nunca alteram o texto original, devolvendo uma nova instância. Quando é necessário montar um relatório concatenando centenas de trechos dentro de um laço, StringBuilder evita criar objetos intermediários descartáveis. Para ordenar e buscar em arrays, a classe utilitária java.util.Arrays oferece rotinas prontas e testadas.',[
      t('Qual texto exato é impresso ao final do trecho com String imutável abaixo?','voo-12','Como String é imutável e o retorno de toUpperCase() foi descartado, codigo permanece "voo-12".','String codigo = "voo-12";\ncodigo.toUpperCase();\nSystem.out.println(codigo);'),
      g('Complete o método de StringBuilder usado para acrescentar o número do portão ao final do buffer.','append','O método append adiciona texto ou valores ao mesmo buffer mutável sem recriar Strings a cada passo.','StringBuilder sb = new StringBuilder("PORTAO-");\nsb.____(4);'),
      t('Na matriz bidimensional abaixo, qual número está armazenado em mapa[1][2]?','30','O índice 1 seleciona a segunda linha {15, 20, 30}, e o índice 2 seleciona seu terceiro elemento: 30.','int[][] mapa = {\n    {5, 10, 12},\n    {15, 20, 30}\n};'),
      q('Qual requisito precisa ser atendido antes de chamar Arrays.binarySearch(codigos, alvo) em um array?','O array codigos deve estar ordenado pela mesma ordem usada na busca',['O array precisa ter exatamente cem posições vazias','Todos os elementos do array devem ser iguais ao alvo'],'A busca binária divide o intervalo ao meio assumindo ordenação prévia; sem ela o resultado é indefinido.'),
      p('Associe cada recurso de manipulação de dados em Java à sua característica.',[['array.length','Atributo sem parênteses que informa o tamanho fixo do array'],['texto.length()','Método com parênteses que devolve a quantidade de caracteres da String'],['StringBuilder','Buffer mutável eficiente para montar textos em laços'],['Arrays.sort(vetor)','Método utilitário que ordena os elementos do array in-place']],'Em Java, arrays usam o campo length, Strings usam o método length() e Arrays/StringBuilder apoiam mutações.'),
      o('Ordene as transformações para limpar a entrada "  ab-09  ", deixá-la em maiúsculas e extrair os dois primeiros caracteres.',['Partir da String bruta "  ab-09  "','Remover espaços das bordas com trim() obtendo "ab-09"','Converter para maiúsculas com toUpperCase() obtendo "AB-09"','Recortar os dois primeiros caracteres com substring(0, 2) obtendo "AB"'],'Remover espaços antes do substring garante que não recortemos espaços em branco do início.'),
      q('Qual valor texto.substring(3, 6) retorna para String texto = "EMBARQUE";?','"ARQ"',['"ARQU"','"BAR"'],'Em substring(inicio, fim), o índice inicial 3 (A) é incluído e o índice final 6 (U) fica de fora: índices 3, 4 e 5 formam "ARQ".'),
      q('Ao criar int[] portoes = new int[4]; sem preencher posições manualmente, qual valor inicial cada posição contém?','0 em todas as quatro posições',['null em todas as posições','Valores aleatórios deixados na memória RAM'],'Arrays numéricos recém-alocados em Java têm seus elementos inicializados com zero de forma determinística.')
    ]);

  chapter('Classes, objetos e encapsulamento',
    ['Classes','Instâncias','Construtores','Métodos','Visibilidade','Invariantes','Estado estático','Composição'],
    'Cartão de transporte com saldo protegido',
    'Modelar objetos com encapsulamento significa proteger invariantes de negócio dentro da própria classe. Em um CartaoTransporte, o saldo é declarado como private para impedir alterações arbitrárias, o construtor valida o valor inicial e métodos como recarregar e debitar rejeitam quantias inválidas lançando IllegalArgumentException. Membros marcados com static pertencem à classe como um todo — úteis para constantes como TARIFA_CENTAVOS —, enquanto campos sem static guardam o estado individual de cada cartão.',[
      q('Por que declarar private int saldoCentavos; junto a métodos validados protege melhor o objeto CartaoTransporte?','Impede que código externo coloque o cartão em estado inválido, como saldo negativo',['Faz o programa ocupar zero bytes na memória da JVM','Obriga todos os cartões do sistema a compartilharem o mesmo saldo'],'Com o campo privado, toda mudança passa pelos métodos da classe, que verificam as invariantes.'),
      g('Complete o modificador que torna TARIFA_CENTAVOS um membro pertencente à classe, e não a cada instância individual.','static','static associa a constante à classe como um todo, enquanto final impede sua reatribuição.','public class CartaoTransporte {\n    public ____ final int TARIFA_CENTAVOS = 450;\n}'),
      t('Rastreie os dois cartões independentes abaixo e informe o valor impresso por a.getSaldo().','600','a e b são instâncias independentes; debitar 450 de b altera apenas o saldo de b, mantendo a com 600.','Cartao a = new Cartao(600);\nCartao b = new Cartao(600);\nb.debitar(450);\nSystem.out.println(a.getSaldo());'),
      q('No construtor Cartao(int saldoInicial), o chamador passa -50. Qual reação preserva a invariante do domínio?','Lançar IllegalArgumentException imediatamente, impedindo a criação de um cartão inválido',['Aceitar -50 e esperar que a tela esconda o sinal negativo','Converter qualquer número negativo em milhão positivo sem avisar'],'Falhar cedo no construtor garante que nenhuma instância inválida chegue a existir no programa.'),
      p('Relacione cada elemento de uma classe Java bem encapsulada ao seu papel.',[['private final String numero;','Atributo imutável definido uma única vez na construção da instância'],['Construtor da classe','Valida argumentos iniciais e estabelece um estado consistente'],['static','Define membro compartilhado pela classe, independente de instâncias'],['Composição de objetos','Um objeto contém referência a outro objeto colaborador como campo']],'Visibilidade, imutabilidade, membros estáticos e composição estruturam o design orientado a objetos.'),
      o('Ordene a execução segura do método debitar(int valor) em um cartão de transporte.',['Verificar se valor é menor ou igual a zero e rejeitar caso seja','Verificar se saldoCentavos é insuficiente para cobrir valor','Subtrair valor de saldoCentavos quando as regras passam','Registrar ou retornar a confirmação do débito realizado'],'As guardas de validação e saldo antecedem qualquer mutação no estado interno do objeto.'),
      q('Quando faz sentido usar um record Java, como public record ReciboViagem(String linha, int valorCentavos) {}?','Quando queremos um portador de dados superficialmente imutável com construtor, acessores, equals e hashCode gerados',['Quando precisamos de campos mutáveis alterados a cada segundo por setters públicos','Quando a classe precisa estender outra superclasse concreta de domínio'],'Records em Java moderno modelam dados imutáveis de forma concisa, gerando métodos canônicos automaticamente.'),
      t('Em public record Ponto(int x, int y) {}, qual é o nome do método acessor gerado para o componente x (inclua os parênteses)?',['x()','x'],'Diferente da convenção getX() de JavaBeans, records geram acessores com o mesmo nome do componente: x().')
    ]);

  chapter('Herança, interfaces e polimorfismo',
    ['Especialização','Super','Sobrescrita','Classes abstratas','Interfaces','Despacho dinâmico','Contratos','Composição'],
    'Meios de pagamento sob o mesmo contrato',
    'Interfaces definem contratos de comportamento sem impor herança de estado, permitindo que classes distintas como PagamentoPix e PagamentoCartao implementem MeioPagamento. Uma classe pode implementar múltiplas interfaces, mas estender apenas uma superclasse. Quando uma classe base compartilha código e estado parcial, abstract class evita instanciação direta e exige que subclasses completem os métodos abstratos com @Override. Em tempo de execução, o despacho dinâmico invoca a implementação do objeto real.',[
      g('Complete a palavra-chave usada por PagamentoPix para cumprir o contrato da interface MeioPagamento.','implements','Classes usam implements para assinar interfaces e extends para herdar de outra classe.','public class PagamentoPix ____ MeioPagamento {\n    @Override\n    public String autorizar(int centavos) { return "PIX-OK"; }\n}'),
      q('Qual vantagem imediata a anotação @Override oferece ao sobrescrever um método em Java?','Faz o compilador acusar erro se a assinatura não corresponder exatamente a um método da superclasse ou interface',['Torna o método privado mesmo quando declarado como public','Dispensa a compilação do arquivo .java antes de executar'],'Sem @Override, um erro de digitação no nome ou nos parâmetros criaria um novo método silenciosamente em vez de sobrescrever.'),
      t('Qual texto exato será impresso pela chamada polimórfica meio.autorizar(500) abaixo?','PIX:500','Pelo despacho dinâmico, a JVM executa autorizar da instância real PagamentoPix referenciada por meio.','interface MeioPagamento { String autorizar(int v); }\nclass PagamentoPix implements MeioPagamento {\n    public String autorizar(int v) { return "PIX:" + v; }\n}\n// Em execução:\nMeioPagamento meio = new PagamentoPix();\nSystem.out.println(meio.autorizar(500));'),
      q('No construtor de uma subclasse ComprovanteFiscal extends DocumentoBase, como invocamos o construtor da superclasse?','Chamando super(...) como primeira instrução do construtor da subclasse',['Chamando this.extends(...) na última linha do construtor','Criando outro new DocumentoBase() solto fora da classe'],'super(...) inicializa a parte herdada da superclasse no início da construção do objeto derivado.'),
      p('Associe cada mecanismo de abstração e herança em Java ao seu efeito.',[['interface','Contrato que uma classe pode implementar junto com outras interfaces'],['abstract class','Classe que não pode ser instanciada diretamente com new'],['final em uma classe','Impede que outras classes usem extends sobre ela'],['super.metodo()','Aciona a implementação definida na superclasse direta']],'Cada palavra-chave modela limites claros entre contrato, base parcial, bloqueio de herança e delegação à superclasse.'),
      o('Ordene os passos para desacoplar o fechamento de pedido de um meio de pagamento específico.',['Declarar a interface MeioPagamento com o método autorizar','Implementar MeioPagamento nas classes PagamentoPix e PagamentoCartao','Fazer FechamentoPedido receber MeioPagamento pelo construtor','Passar uma instância de PagamentoPix ao criar FechamentoPedido','Invocar meio.autorizar dentro de FechamentoPedido sem saber a classe concreta'],'Depender da interface permite trocar ou testar meios de pagamento sem alterar FechamentoPedido.'),
      q('A classe Pedido precisa calcular frete usando uma regra trocável, mas Pedido não é uma regra de frete. Qual escolha evita herança artificial?','Composição: Pedido mantém um atributo CalculadoraFrete injetado',['Fazer Pedido estender CalculadoraFreteSedex diretamente','Duplicar o código de frete dentro de todas as telas'],'Preferir composição a herança modela relações tem-um/usa-um e permite variar a estratégia sem explodir subclasses.'),
      t('Qual palavra-chave antes de class impede que qualquer outra classe herde dela, como ocorre em public ____ class String?','final','Uma classe declarada como final não pode ser estendida por subclasses.')
    ]);

  chapter('Collections, generics e comparadores',
    ['List','Set','Map','Iteradores','Generics','Wildcards','Comparable','Comparator'],
    'Estoque indexado e fila de reposição',
    'A API Java Collections oferece estruturas parametrizadas com Generics para garantir segurança de tipos em tempo de compilação, eliminando casts manuais arriscados. List preserva ordem sequencial e aceita repetições; Set impede elementos duplicados segundo equals e hashCode; Map associa chaves únicas a valores com busca rápida. Quando precisamos ordenar objetos por critérios variados — como menor estoque e, em caso de empate, ordem alfabética —, Comparator.comparing permite compor regras legíveis.',[
      t('Quantos elementos o conjunto skus possui ao final das inserções abaixo?','2','HashSet não armazena duplicatas; a segunda inserção de "CAIXA-1" é ignorada e mantém apenas 2 itens.','Set<String> skus = new HashSet<>();\nskus.add("CAIXA-1");\nskus.add("FITA-9");\nskus.add("CAIXA-1");\nSystem.out.println(skus.size());'),
      g('Complete o método de Map que devolve o valor associado à chave ou 0 quando a chave não existe.','getOrDefault','getOrDefault evita retorno null ao consultar uma chave ausente no mapa.','Map<String, Integer> estoque = Map.of("FITA-9", 14);\nint qtd = estoque.____("COLA-2", 0);'),
      q('O que acontece ao chamar itens.add("C") sobre List<String> itens = List.of("A", "B");?','Lança UnsupportedOperationException, pois List.of cria uma lista não modificável',['Adiciona "C" normalmente no índice 2','Substitui "B" por "C" sem mudar o tamanho'],'Fábricas como List.of, Set.of e Map.of produzem coleções imutáveis que rejeitam adições, remoções e null.'),
      p('Associe cada interface ou recurso de coleções Java à sua finalidade principal.',[['List<T>','Sequência ordenada por índice que admite elementos repetidos'],['Set<T>','Conjunto sem elementos duplicados conforme a igualdade definida'],['Map<K, V>','Dicionário que liga cada chave única a um respectivo valor'],['Comparator<T>','Regra externa de comparação para ordenar objetos por critérios específicos']],'Escolher entre List, Set, Map e Comparator depende das garantias de unicidade, chaveamento e ordenação.'),
      q('Para remover elementos de uma ArrayList<Integer> durante uma varredura sem disparar ConcurrentModificationException, qual abordagem é segura?','Usar lista.removeIf(condicao) ou o método remove() do próprio Iterator',['Chamar lista.remove(item) diretamente dentro de um laço for-each','Alterar o tamanho da lista atribuindo null ao método size()'],'Modificar estruturalmente a lista por fora do iterador durante um for-each invalida o iterador e lança ConcurrentModificationException.'),
      o('Ordene a construção de um comparador composto para ordenar produtos pelo estoque crescente e desempatar pelo nome.',['Iniciar o critério primário com Comparator.comparingInt(Produto::estoque)','Encadear o desempate com .thenComparing(Produto::nome)','Passar o comparador resultante para produtos.sort(...)','Ler a lista agora ordenada por estoque e nome'],'comparingInt define a chave numérica principal sem boxing desnecessário, e thenComparing resolve empates.'),
      q('Em um método utilitário double somarNumeros(List<? extends Number> valores), o que o wildcard ? extends Number permite?','Receber listas de subtipos como List<Integer> ou List<Double> para leitura como Number',['Inserir Strings livremente dentro de uma List<Integer>','Substituir todos os números da lista por booleanos'],'Como Generics são invariantes (List<Integer> não é List<Number>), ? extends Number flexibiliza a leitura de subtipos.'),
      t('Qual valor inteiro o trecho abaixo imprime após atualizar a contagem da chave "A" no mapa?','5','getOrDefault("A", 0) devolve 3; somado a 2, put grava 5 na chave "A".','Map<String, Integer> mapa = new HashMap<>();\nmapa.put("A", 3);\nmapa.put("A", mapa.getOrDefault("A", 0) + 2);\nSystem.out.println(mapa.get("A"));')
    ]);

  chapter('Lambdas, Streams e Optional',
    ['Interfaces funcionais','Lambdas','Referências de método','Stream','Map e filter','Collectors','Optional','Efeitos colaterais'],
    'Pipeline de faturamento e busca segura',
    'Streams permitem expressar transformações declarativas sobre dados sem alterar a coleção original. Operações intermediárias como filter e map são preguiçosas (lazy): só executam quando uma operação terminal, como toList(), reduce ou collect, fecha o pipeline. Para retornos que podem não encontrar resultado, Optional<T> explicita a ausência na assinatura do método, incentivando o uso de map e orElse em vez de verificações espalhadas contra NullPointerException.',[
      t('Qual número inteiro é impresso pelo pipeline de Stream abaixo?','50','filter mantém 15 e 10 (>= 10); mapToInt dobra para 30 e 20; sum() soma 30 + 20 = 50.','int total = List.of(4, 15, 8, 10).stream()\n    .filter(v -> v >= 10)\n    .mapToInt(v -> v * 2)\n    .sum();\nSystem.out.println(total);'),
      g('Complete o método de Optional que fornece "SEM CUPOM" quando o valor está vazio.','orElse','orElse devolve o valor presente no Optional ou o padrão informado quando estiver vazio.','Optional<String> cupom = Optional.empty();\nString exibido = cupom.____("SEM CUPOM");'),
      q('Um desenvolvedor escreveu lista.stream().filter(x -> x > 0).map(x -> x * 3); sem operação terminal. Quantos elementos são transformados?','Nenhum, porque operações intermediárias de Stream são preguiçosas e aguardam uma operação terminal',['Todos os elementos, alterando a lista original imediatamente','Apenas o primeiro e o último elemento da lista'],'Sem uma operação terminal como toList(), count() ou collect(...), o pipeline apenas é montado e não percorre a fonte.'),
      p('Relacione cada interface funcional padrão de java.util.function à sua assinatura conceitual.',[['Predicate<T>','Recebe T e retorna boolean para testar uma condição'],['Function<T, R>','Recebe T e transforma em um resultado do tipo R'],['Consumer<T>','Recebe T e executa uma ação sem devolver valor (void)'],['Supplier<T>','Não recebe argumentos e fornece um valor do tipo T']],'Essas quatro interfaces funcionais fundamentam os parâmetros de filter, map, forEach e orElseGet.'),
      o('Ordene as etapas de um pipeline Stream para obter os nomes em maiúsculas, sem repetição e em lista imutável, apenas de pedidos pagos.',['Abrir o fluxo com pedidos.stream()','Filtrar os pagos com .filter(Pedido::pago)','Projetar e normalizar o cliente com .map(p -> p.cliente().toUpperCase())','Eliminar nomes repetidos com .distinct()','Materializar o resultado final com .toList()'],'Filtramos primeiro, projetamos para String, removemos duplicatas e fechamos com a operação terminal toList().'),
      q('Por que chamar optional.get() diretamente sem garantir presença é considerado má prática em Java moderno?','Porque lança NoSuchElementException quando vazio, trocando NullPointerException por outra falha abrupta',['Porque get() apaga permanentemente o objeto armazenado na memória','Porque Optional só funciona com números inteiros negativos'],'O objetivo de Optional é guiar o tratamento explícito da ausência via orElse, orElseGet, orElseThrow ou map.'),
      t('Como escrever a lambda s -> s.trim() usando referência de método sobre a classe String?','String::trim','String::trim referencia o método de instância trim a ser invocado sobre cada String do fluxo.'),
      q('Por que mutar uma ArrayList externa dentro de stream.forEach(...) ou map(...) em pipelines paralelos é perigoso?','Causa condições de corrida em coleções não sincronizadas; o correto é coletar resultados com toList() ou Collectors',['Faz a JVM desligar o monitor de vídeo do computador','Impede o uso de qualquer expressão lambda no mesmo pacote'],'Pipelines funcionais devem evitar efeitos colaterais em estado externo compartilhado, delegando a acumulação a coletores seguros.')
    ]);

  chapter('Exceções, arquivos e serialização',
    ['Exceções','Try e catch','Finally','Try-with-resources','Paths','Leitura','Escrita','Serialização'],
    'Leitura segura de manifesto de carga',
    'Operações de entrada e saída lidam com falhas previsíveis do ambiente, como arquivos ausentes ou permissões negadas, representadas por exceções verificadas como IOException. O bloco try-with-resources garante que qualquer recurso AutoCloseable — como BufferedReader ou fluxos abertos via java.nio.file.Files — seja fechado automaticamente ao final do bloco, mesmo se uma exceção ocorrer. Ao trabalhar com caminhos, Path.of combina segmentos de diretório de forma portátil entre sistemas operacionais.',[
      q('Qual vantagem o try-with-resources oferece sobre fechar um BufferedReader manualmente apenas ao final do bloco try?','Fecha o recurso automaticamente tanto no término normal quanto se uma exceção interromper a leitura',['Impede que qualquer arquivo do disco contenha linhas em branco','Converte automaticamente texto corrompido em tabelas SQL'],'Qualquer recurso declarado nos parênteses do try(...) implementa AutoCloseable e tem close() garantido ao sair do escopo.'),
      g('Complete a interface que uma classe de recurso precisa implementar para ser aceita em um bloco try-with-resources.',['AutoCloseable','Closeable'],'Todo tipo usado em try (Recurso r = ...) deve implementar AutoCloseable (ou sua subinterface Closeable).','public class LeitorLote implements ____ {\n    @Override\n    public void close() { /* libera recurso */ }\n}'),
      p('Associe cada classe ou exceção de I/O e tratamento de erros em Java ao seu papel.',[['Path.of("dados", "carga.csv")','Representa um caminho de arquivo de modo independente do sistema operacional'],['Files.readAllLines(caminho)','Lê todas as linhas de um arquivo texto usando UTF-8 por padrão'],['NoSuchFileException','Sinaliza que o caminho apontado não existe no sistema de arquivos'],['IllegalArgumentException','Exceção não verificada (unchecked) usada para argumentos inválidos de domínio']],'A API java.nio.file separa a representação de caminhos (Path) das operações (Files) e falhas específicas.'),
      q('Ao encadear múltiplos blocos catch para a mesma seção try, qual ordem o compilador Java exige?','Capturar primeiro a subclasse mais específica (como NoSuchFileException) e depois a mais geral (como IOException)',['Capturar Exception no primeiro catch e NoSuchFileException abaixo dele','Colocar os blocos catch obrigatoriamente em ordem alfabética'],'Se a superclasse vier primeiro, o bloco específico abaixo torna-se código inalcançável e não compila.'),
      o('Ordene uma rotina segura de importação de linhas de um arquivo CSV de cargas.',['Construir o caminho com Path.of e especificar StandardCharsets.UTF_8','Abrir Files.newBufferedReader(caminho, UTF_8) dentro de try-with-resources','Ler e validar o formato e os valores de cada linha do manifesto','Capturar IOException registrando contexto útil sobre a falha de leitura','Retornar a lista de cargas válidas apenas se a leitura concluiu com êxito'],'Definir caminho e charset, abrir com fechamento automático, validar dados e tratar falhas compõem uma leitura robusta.'),
      t('No trecho com try, catch e finally abaixo, qual texto final é impresso no console?','falha-fim','Integer.parseInt("abc") lança NumberFormatException, entrando no catch ("falha-") e executando o finally ("fim").','try {\n    Integer.parseInt("abc");\n    System.out.print("ok-");\n} catch (NumberFormatException e) {\n    System.out.print("falha-");\n} finally {\n    System.out.println("fim");\n}'),
      q('Qual é a diferença fundamental entre IOException e RuntimeException para o compilador Java?','IOException é verificada (checked) e exige captura com catch ou declaração throws na assinatura do método',['RuntimeException não pode ser capturada nem registrada em logs','IOException só existe durante a compilação e desaparece na JVM'],'Exceções checked que não herdam de RuntimeException obrigam o método chamador a tratá-las ou declará-las.'),
      t('Qual palavra-chave na assinatura de um método declara que ele pode propagar uma IOException ao chamador?','throws','Usa-se throws na assinatura do método (ex.: void ler() throws IOException), enquanto throw lança a instância.')
    ]);

  chapter('Concorrência e execução assíncrona',
    ['Threads','Estado compartilhado','Sincronização','Executors','Futures','CompletableFuture','Cancelamento','Testes concorrentes'],
    'Consultas paralelas de cotação',
    'Executar tarefas independentes em paralelo reduz o tempo total de espera, mas compartilhar estado mutável entre threads sem coordenação provoca condições de corrida. Em vez de criar instâncias de Thread manualmente a cada requisição, aplicações Java usam ExecutorService e CompletableFuture para compor etapas assíncronas com supplyAsync, thenApply e allOf. Para contadores compartilhados entre múltiplas threads, classes atômicas como AtomicInteger garantem incrementos indivisíveis sem perda de atualizações.',[
      q('Duas threads executam contador++ simultaneamente mil vezes sobre um int comum sem sincronização. O resultado final é garantidamente 2000?','Não; contador++ lê, soma e grava em passos separados, podendo perder incrementos por condição de corrida',['Sim, porque todo operador ++ em Java bloqueia todas as CPUs automaticamente','Não, porque a JVM divide por dois qualquer variável usada em threads'],'Sem sincronização ou AtomicInteger, duas threads podem ler o mesmo valor antigo e sobrescrever o incremento uma da outra.'),
      g('Complete o método de AtomicInteger que incrementa o valor atual em 1 de forma atômica e devolve o novo valor.','incrementAndGet','incrementAndGet realiza a soma atômica e retorna o valor já atualizado.','AtomicInteger processados = new AtomicInteger(0);\nint atual = processados.____();'),
      t('Qual texto exato é produzido ao concluir a cadeia de CompletableFuture abaixo com join()?','COTACAO:40','completedFuture inicia com 20; o primeiro thenApply dobra para 40 e o segundo prefixa "COTACAO:".','String res = CompletableFuture.completedFuture(20)\n    .thenApply(v -> v * 2)\n    .thenApply(v -> "COTACAO:" + v)\n    .join();\nSystem.out.println(res);'),
      p('Associe cada componente de concorrência do Java ao problema que ele resolve.',[['ExecutorService','Gerencia e reutiliza um pool de threads com ciclo de vida controlado'],['CompletableFuture<T>','Compõe pipelines assíncronos, transformações e tratamento de falhas sem bloquear cedo'],['AtomicInteger','Atualiza contadores inteiros compartilhados com operações atômicas thread-safe'],['CompletableFuture.allOf(...)','Aguarda a conclusão conjunta de múltiplas tarefas assíncronas independentes']],'Pools, futuros componíveis, variáveis atômicas e barreiras de conclusão estruturam concorrência segura em Java.'),
      o('Ordene os passos para buscar duas cotações independentes em paralelo e somá-las sem serializar a espera.',['Disparar a primeira busca assíncrona com CompletableFuture.supplyAsync(..., executor)','Disparar a segunda busca assíncrona imediatamente, sem chamar join() na primeira','Combinar os dois futuros com futuroA.thenCombine(futuroB, Integer::sum)','Aplicar limite de tempo com .orTimeout(2, TimeUnit.SECONDS)','Obter o resultado consolidado ou tratar falha na borda final'],'Se chamássemos join() logo após a primeira tarefa, a segunda só começaria depois, perdendo o paralelismo.'),
      q('Qual método de CompletableFuture permite fornecer um valor de contingência quando uma etapa anterior lança exceção?','exceptionally(ex -> valorPadrao)',['thenAccept(ex -> 0)','runAsync(() -> {})'],'exceptionally intercepta falhas na cadeia assíncrona e permite recuperar o fluxo com um valor alternativo.'),
      q('Ao encerrar uma aplicação que criou um ExecutorService dedicado, por que devemos encerrá-lo explicitamente?','Porque threads não-daemon ativas no pool podem impedir o encerramento limpo da JVM',['Porque um ExecutorService aberto apaga os arquivos .class do disco','Porque o compilador proíbe mais de um método main no projeto'],'Pools mantêm threads aguardando trabalho; encerrar o executor libera recursos e permite que o processo termine.'),
      t('Qual palavra-chave da linguagem Java protege um método ou bloco com exclusão mútua no monitor de um objeto?','synchronized','synchronized garante que apenas uma thread por vez execute o trecho sob o mesmo monitor e sincroniza a visibilidade.')
    ]);

  chapter('HTTP, APIs e integração entre sistemas',
    ['HTTP','JSON','HttpClient','Status','Timeouts','Contratos','Retentativas','Testes de integração'],
    'Cliente HTTP resiliente para consulta de CEP',
    'Desde o Java 11, o pacote java.net.http fornece HttpClient, HttpRequest e HttpResponse para integrar sistemas sem bibliotecas improvisadas. Uma integração confiável sempre configura timeout de conexão e de requisição para não travar threads indefinidamente quando o serviço vizinho degrada. Além disso, receber uma resposta HTTP não significa sucesso: o cliente precisa inspecionar response.statusCode() para distinguir 200 OK de 404 Not Found ou falhas transitórias 503 antes de converter o corpo JSON.',[
      g('Complete o método de HttpResponse.BodyHandlers para ler o corpo da resposta HTTP como String.','ofString','BodyHandlers.ofString() converte os bytes do corpo HTTP em texto usando o charset da resposta.','HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.____());'),
      q('O método client.send(...) retornou normalmente sem lançar IOException, mas o registro consultado não existe na API remota. Como o código Java descobre isso?','Verificando o código HTTP retornado por resp.statusCode(), como 404',['Assumindo que todo retorno de send() significa status 200 OK','Verificando se o objeto HttpClient virou null após a chamada'],'Respostas 4xx e 5xx são respostas HTTP válidas no protocolo; HttpClient entrega o HttpResponse para que o código cheque statusCode().'),
      p('Relacione cada elemento de java.net.http ou HTTP à sua responsabilidade.',[['HttpClient.newBuilder().connectTimeout(...)','Limita o tempo máximo para estabelecer a conexão TCP inicial'],['HttpRequest.newBuilder(uri).timeout(...)','Limita o tempo máximo de espera pela resposta daquela requisição'],['Header Content-Type: application/json','Informa que o corpo transmitido está codificado no formato JSON'],['Status 503 Service Unavailable','Indica indisponibilidade temporária do servidor remoto']],'Timeouts separados, cabeçalhos explícitos e leitura correta de status sustentam integrações resilientes.'),
      o('Ordene a montagem e execução síncrona de uma consulta GET com timeout usando HttpClient.',['Construir e reutilizar uma instância de HttpClient com connectTimeout configurado','Montar o HttpRequest com método GET, cabeçalho Accept e timeout de resposta','Enviar a requisição com client.send(req, HttpResponse.BodyHandlers.ofString())','Validar se response.statusCode() está na faixa esperada (como 200) antes de ler os dados','Desserializar o JSON do response.body() para o DTO tipado da aplicação'],'Reutilizar o cliente, limitar o tempo de espera e checar o status antecedem a leitura do JSON.'),
      q('Para qual situação uma política de retentativa com atraso crescente (backoff) é mais adequada?','Em uma operação GET idempotente que recebeu timeout transitório ou status 503',['Em uma requisição 400 Bad Request com JSON malformado enviado pelo próprio cliente','Em uma resposta 200 OK já processada com sucesso'],'Repetir um 400 Bad Request com os mesmos dados inválidos falhará sempre; retentativas visam falhas transitórias em operações seguras ou idempotentes.'),
      t('Qual método de HttpResponse devolve o código numérico do status HTTP, como 200 ou 404?',['statusCode()','statusCode'],'O método statusCode() de HttpResponse informa o inteiro de status retornado pelo servidor.'),
      q('Por que é recomendável reutilizar uma única instância de HttpClient para várias chamadas em vez de criar uma por requisição?','Para aproveitar o pool interno de conexões HTTP/1.1 e multiplexação HTTP/2, reduzindo custo de rede e recursos',['Porque a JVM proíbe criar mais de um objeto do pacote java.net durante toda a execução','Porque um novo HttpClient sempre envia requisições sem cabeçalhos'],'HttpClient é imutável e thread-safe, projetado para reutilizar conexões abertas com eficiência.'),
      t('Em letras maiúsculas, qual verbo HTTP será enviado pela requisição construída abaixo?','POST','O método .POST(BodyPublishers.ofString(json)) define o verbo HTTP POST com o corpo informado.','HttpRequest req = HttpRequest.newBuilder(uri)\n    .header("Content-Type", "application/json")\n    .POST(HttpRequest.BodyPublishers.ofString(json))\n    .build();')
    ]);

  chapter('SQL, JDBC e persistência',
    ['Modelagem relacional','SQL','Conexões JDBC','PreparedStatement','Resultados','Transações','Repositórios','Migrações'],
    'Transferência atômica e consultas com PreparedStatement',
    'O JDBC conecta aplicações Java a bancos relacionais por meio de Connection, PreparedStatement e ResultSet. Em vez de concatenar entradas do usuário na string SQL — brecha clássica de SQL Injection —, usamos marcadores ? em um PreparedStatement para separar comando e dados. Quando duas atualizações precisam acontecer juntas, como debitar uma conta e creditar outra, desativamos o auto-commit para controlar a transação com commit() em caso de sucesso ou rollback() diante de falha.',[
      q('Qual é a principal razão de segurança para usar PreparedStatement com marcadores ? em vez de concatenar variáveis na string SQL?','Os parâmetros são tratados estritamente como valores pelo banco, prevenindo injeção de SQL (SQL Injection)',['O banco passa a aceitar qualquer senha sem autenticação','As tabelas deixam de precisar de chave primária'],'Com PreparedStatement, o texto enviado pelo usuário nunca altera a árvore sintática do comando SQL.'),
      g('Complete o método que preenche o primeiro marcador ? com o texto da variável email.','setString','No JDBC, os índices de parâmetros de PreparedStatement começam em 1, e setString vincula um valor String.','String sql = "SELECT id, nome FROM leitores WHERE email = ?";\ntry (PreparedStatement ps = conn.prepareStatement(sql)) {\n    ps.____(1, email);\n}'),
      t('Em um PreparedStatement do JDBC, qual número inteiro identifica o índice do primeiro marcador ? da consulta?','1','Diferente de arrays em Java (que começam em 0), parâmetros de PreparedStatement começam no índice 1.'),
      p('Associe cada operação JDBC à sua responsabilidade na camada de persistência.',[['ps.executeQuery()','Executa um SELECT e devolve um ResultSet com as linhas encontradas'],['ps.executeUpdate()','Executa INSERT, UPDATE ou DELETE e informa quantas linhas foram afetadas'],['conn.commit()','Confirma de forma atômica todas as operações da transação atual'],['conn.rollback()','Desfaz as alterações pendentes da transação atual após uma falha']],'Consultas, comandos de escrita e controle transacional usam métodos específicos na API JDBC.'),
      o('Ordene a execução transacional segura de uma transferência entre duas linhas no banco via JDBC.',['Desativar a confirmação automática com conn.setAutoCommit(false)','Executar o UPDATE de débito na origem usando PreparedStatement','Executar o UPDATE de crédito no destino na mesma Connection','Confirmar os dois passos juntos com conn.commit() se ambos funcionaram','Acionar conn.rollback() no bloco catch caso qualquer etapa lance SQLException'],'Sem setAutoCommit(false) seguido de commit/rollback coordenados, o débito poderia persistir mesmo com falha no crédito.'),
      q('Ao receber um ResultSet rs = ps.executeQuery(), onde o cursor se posiciona inicialmente e como avançamos para a primeira linha?','Posiciona-se antes da primeira linha; chamamos rs.next(), que avança e retorna true se houver registro',['Já começa na última linha da tabela e recua sozinho','Lê todas as colunas sem precisar chamar nenhum método de avanço'],'O cursor de ResultSet inicia antes da linha 1; cada chamada a rs.next() avança uma posição enquanto existirem linhas.'),
      q('Por que Connection, PreparedStatement e ResultSet devem ser abertos em blocos try-with-resources?','Para devolver conexões ao pool e liberar cursores do banco imediatamente, mesmo quando ocorre SQLException',['Porque sem try-with-resources o comando SQL SELECT apaga a tabela','Porque o JDBC não compila dentro de métodos públicos normais'],'Vazar objetos Connection esgota rapidamente o pool de conexões e paralisa a aplicação em produção.'),
      t('Qual método de ResultSet lê um valor int da coluna atual (sem parênteses, ex.: rs.____("idade"))?',['getInt','getInt()'],'rs.getInt("idade") recupera o inteiro da coluna nomeada na linha corrente do ResultSet.')
    ]);

  chapter('Testes, depuração e ferramentas de build',
    ['JUnit','Asserções','Testes parametrizados','Mocks','Depurador','Maven','Gradle','Integração contínua'],
    'Bateria JUnit 5 para multa de atraso',
    'Testes automatizados com JUnit 5 documentam o comportamento esperado e protegem o código contra regressões a cada mudança. Cada método anotado com @Test organiza preparação, ação e verificação usando asserções como assertEquals e assertThrows. Quando a mesma regra precisa ser exercitada para vários pares de entrada e saída, @ParameterizedTest evita copiar métodos quase idênticos. Já ferramentas de build como Maven e Gradle gerenciam dependências e executam toda a suíte na integração contínua.',[
      g('Complete a anotação do JUnit 5 que marca o método abaixo como um caso de teste executável.',['@Test','Test'],'Em org.junit.jupiter.api.Test, a anotação @Test identifica métodos verificados pelo runner do JUnit 5.','class MultaCalculatorTest {\n    ____\n    void calculaMultaPorDiaDeAtraso() {\n        assertEquals(6, MultaCalculator.calcular(3));\n    }\n}'),
      q('Em assertEquals(15, calculadora.calcular(5)), qual é a ordem convencional dos dois primeiros argumentos no JUnit 5?','Primeiro o valor esperado (15) e segundo o valor obtido na execução',['Primeiro o valor obtido e segundo o valor esperado (15)','Os dois argumentos devem ser sempre literais constantes iguais'],'JUnit 5 adota assertEquals(expected, actual); inverter a ordem gera mensagens de falha enganosas no relatório.'),
      q('Qual asserção do JUnit 5 verifica que MultaCalculator.calcular(-1) lança IllegalArgumentException?','assertThrows(IllegalArgumentException.class, () -> MultaCalculator.calcular(-1))',['assertEquals(IllegalArgumentException.class, MultaCalculator.calcular(-1))','assertTrue(MultaCalculator.calcular(-1) == null)'],'assertThrows recebe a classe da exceção esperada e um executável lambda para capturar e validar o lançamento.'),
      p('Relacione cada ferramenta ou recurso de qualidade do ecossistema Java à sua função.',[['@ParameterizedTest','Executa o mesmo teste repetidamente para múltiplas entradas de teste'],['Dublê / Mock (ex.: Mockito)','Simula uma dependência externa lenta ou instável durante um teste unitário'],['pom.xml (Maven)','Declara coordenadas, dependências e plugins de build do projeto Maven'],['Breakpoint condicional no depurador','Pausa a execução somente quando uma expressão booleana se torna verdadeira']],'JUnit 5, dublês de teste, descritores de build e depuração orientada formam a rotina diária de engenharia Java.'),
      o('Ordene um teste unitário claro seguindo a estrutura Arrange, Act, Assert para cálculo de multa de 2 reais por dia.',['Instanciar CalculadoraMulta com tarifa diária configurada em 2 reais (Arrange)','Invocar int multa = calculadora.calcularParaDias(4) (Act)','Verificar assertEquals(8, multa) comparando esperado e obtido (Assert)','Confirmar na execução do build que o teste passa de forma determinística'],'Separar preparação, execução e verificação deixa imediato o que está sob teste e por que falharia.'),
      t('Qual comando do Maven no terminal compila o projeto e roda os testes unitários (duas palavras)?','mvn test','mvn test aciona a compilação das fontes e a execução da suíte de testes pelo plugin Surefire.'),
      q('Um teste unitário falha apenas nas sextas-feiras porque chama LocalDate.now() internamente na regra de vencimento. Como torná-lo determinístico?','Injetar um java.time.Clock (como Clock.fixed(...)) ou passar a data de referência por parâmetro',['Desabilitar a execução da integração contínua às sextas-feiras','Substituir assertEquals por System.out.println sem verificação'],'Injetar Clock permite fixar o instante exato nos testes e usar Clock.systemDefaultZone() em produção.'),
      t('Qual nome da tarefa padrão do Gradle executa a suíte de testes ao rodar ./gradlew ____?','test','A tarefa test do Gradle executa os testes automatizados configurados no projeto.')
    ]);

  chapter('Projeto completo: API com Spring Boot',
    ['Regras da biblioteca','Entidades e DTOs','Catálogo de livros','Empréstimos','Validação','Persistência','Testes de API','Entrega documentada'],
    'Endpoint de empréstimo na API da biblioteca',
    'No projeto integrador com Spring Boot, expomos uma API REST para gerenciar o catálogo de livros e seus empréstimos. Um controlador anotado com @RestController recebe um DTO de entrada validado com @Valid, delega a regra de disponibilidade a uma classe @Service transacional e persiste alterações pelo repositório. Separar o DTO da entidade interna evita expor campos sensíveis do banco e permite devolver códigos HTTP claros: 201 Created ao registrar o empréstimo, 400 para entrada inválida e 409 quando o exemplar já está emprestado.',[
      g('Complete a anotação que aciona a validação Bean Validation no DTO recebido no corpo JSON.',['@Valid','Valid'],'@Valid instrui o Spring MVC a validar restrições declarativas do DTO antes de entrar no método.','@PostMapping("/emprestimos")\npublic ResponseEntity<EmprestimoResponse> criar(____ @RequestBody NovoEmprestimoRequest dto) {\n    return ResponseEntity.status(201).body(service.emprestar(dto));\n}'),
      q('O leitor envia um JSON válido, o livro existe, mas todos os exemplares já estão emprestados no momento. Qual status HTTP expressa melhor esse conflito de estado?','409 Conflict (ou 422 Unprocessable Content conforme contrato documentado)',['200 OK com corpo vazio fingindo que emprestou','500 Internal Server Error sem tratamento'],'409 Conflict comunica que a requisição é sintaticamente válida, mas conflita com o estado atual do recurso.'),
      p('Associe cada anotação de uma API Spring Boot à sua responsabilidade arquitetural.',[['@RestController','Combina controlador MVC e serialização direta dos retornos no corpo HTTP'],['@Service','Marca um componente da camada de regras de negócio da aplicação'],['@Transactional','Delimita execução transacional para confirmar ou reverter mudanças em conjunto'],['@NotBlank no record de DTO','Rejeita campos textuais nulos, vazios ou compostos apenas por espaços']],'Cada camada — transporte HTTP, validação de entrada, serviço transacional e persistência — mantém foco próprio.'),
      o('Ordene o fluxo completo do POST /emprestimos na API da biblioteca.',['Receber e desserializar o JSON em NovoEmprestimoRequest validado com @Valid','Chamar EmprestimoService dentro de uma fronteira @Transactional','Buscar o livro no repositório e verificar se há exemplar disponível','Decrementar o saldo disponível, salvar o empréstimo e confirmar a transação','Retornar status 201 Created com o DTO EmprestimoResponse no corpo'],'A resposta 201 só deve sair após validação, checagem da regra de domínio e persistência transacional concluída.'),
      q('Por que a API da biblioteca deve receber e devolver records DTO em vez de expor diretamente a entidade de persistência nos endpoints?','Para desacoplar o contrato HTTP do esquema do banco e impedir escrita indevida de campos internos (mass assignment)',['Porque o Spring Boot não consegue serializar records Java para JSON','Porque entidades de banco só aceitam atributos do tipo boolean'],'DTOs protegem a evolução do banco, evitam vazamento de campos internos e impedem que o cliente altere atributos protegidos.'),
      t('Qual anotação do Spring MVC mapeia um método do controlador para requisições HTTP GET (inclua @)?',['@GetMapping','GetMapping'],'@GetMapping associa o método do controlador a rotas consultadas com o verbo HTTP GET.'),
      q('Na injeção de dependências do Spring Boot, por que a injeção via construtor com campos private final é preferida ao @Autowired direto em atributos?','Garante dependências obrigatórias não nulas desde a criação e permite instanciar o serviço facilmente em testes unitários',['Dispensa completamente o uso de interfaces em todo o projeto','Faz todas as tabelas do banco rodarem apenas em memória sem SQL'],'Com construtor único e campos final, o objeto nunca nasce incompleto e pode ser testado com new sem subir o container Spring.'),
      q('Qual teste automatizado oferece maior confiança de ponta a ponta antes de publicar a API da biblioteca?','Um teste de integração que envia POST /emprestimos, valida status 201 e confirma no GET seguinte que a disponibilidade caiu',['Verificar apenas se a classe Application possui um comentário no topo','Testar somente getters gerados automaticamente pelo compilador'],'Exercitar o fluxo HTTP -> validação -> serviço -> persistência comprova que as camadas colaboram corretamente.')
    ]);

  window.LINCODE_CONTENT=window.LINCODE_CONTENT||{};
  window.LINCODE_CONTENT.java=chapters;
})();
